rules.cslSource:
csl v4.0 StockView {
  entity Pallet { attribute weight : Integer required mutable; }
  orgContext Warehouse {}
}

rules.iStarSource:
istar StockRequirements {
  role StockObserver {
    goal StockSafe : Achieve condition {[ Pallet.allInstances()->notEmpty() and Pallet.allInstances()->forAll(p | p.weight >= 0) ]}
  }
}
